oss.Clarify and os.clock()>Cross.Clarify.Expires then Cross.Clarify=nil end\nif yes or no then\nCross.say(\"user\",prompt)\nif Cross.Clarify then\nif no then Cross.Clarify=nil;reply(\"Đã hủy yêu cầu làm rõ.\")\nelse reply(\"Hãy ghi tên chức năng và hành động cụ thể, hoặc trả lời Không để hủy.\")end\nelse reply(\"Không có yêu cầu nào đang chờ xác nhận.\")end\nreturn\nend\nlocal isContext=text:find(\"ten\",1,true)or text:find(\"name\",1,true)or text:find(\"id\",1,true)\nor text:find(\"info\",1,true)or text:find(\"thong tin\",1,true)or text:find(\"nguoi choi\",1,true)\nor text:find(\"bao nhieu nguoi\",1,true)or text:find(\"players\",1,true)or text:find(\"player count\",1,true)or text==\"toi la ai\"or text==\"minh la ai\"or text==\"who am i\"or text==\"what game is this\"or text==\"what game am i playing\"\nif isContext then\nlocal answer=contextAnswer(text)\nif answer then\nCross.say(\"user\",prompt)\nif not Cross.Enabled then Cross.setEnabled(true)end\nreply(answer)\nreturn\nend\nend\nif text==\"goi y\"or text==\"so thich\"or text==\"preferences\"or text==\"suggestions\"then\nCross.say(\"user\",prompt)\nif Cross.Perm an","d Cross.Perm.Ui==false then reply(\"Quyền điều khiển UI của Cross đang tắt.\");return end\nlocal preferences=Cross.Learning and Cross.Learning.Preferences()or{}\nlocal names={}\nfor i=1,math.min(#preferences,5)do local x=preferences[i];table.insert(names,x.tab..\": \"..x.title..\" (\"..x.count..\")\")end\nreply(#names==0 and\"Chưa có chức năng thường dùng được ghi nhận. Dùng và xác nhận một chức năng để bắt đầu.\"or(\"Bạn thường dùng: \"..table.concat(names,\"; \")..\". Hãy ra lệnh nếu muốn dùng; vẫn cần xác nhận.\"))\nreturn\nend\nlocal learnedPage=text:match(\"^danh sach da hoc ?(%d*)$\")or text:match(\"^learned phrases ?(%d*)$\")\nif learnedPage~=nil then\nCross.say(\"user\",prompt)\nif Cross.Perm and Cross.Perm.Ui==false then reply(\"Quyền điều khiển UI của Cross đang tắt.\");return end\nlocal taught=Cross.Learning and Cross.Learning.List()or{}\nlocal names={}\nlocal pages=math.max(1,math.ceil(#taught/10));local page=math.clamp(tonumber(learnedPage)or 1,1,pages)\nfor i=(page-1)*10+1,math.min(#taught,page*10)do table.insert(names,taught[i].phrase..\" → \"..taught[i].command)end\nreply(#names==0 and\"Chưa có câu lệnh nào được dạy.\"or(\"Câu đã học \"..page..\"/\"..pages..\": \"..table.concat(names,\"; \")..(pages>1 and\". Dùng 'danh sách đã học \"..math.min(page+1,pages)..\"' để xem tiếp.\"or\"\")))\nreturn\nend\nlocal learned=Cross.Learning and Cross.Learning.Find(text)\nif learned then\nCross.say(\"user\",prompt)\nif not Cross.Enabled then Cross.setEnabled(true)end\nlocal matched={}\nfor _,e in ipairs(controls())do\nif e.Tab==learned.tab and e.Title==learned.title and e.Kind==learned.kind then table.insert(matched,e)end\nend\nif#matched~=1 then reply(\"Control đã học không còn hoặc bị trùng. Hãy yêu cầu lại bằng tên và tab hiện tại.\");return end\nCross.Clarify=nil\noffer(matched[1],normalize(learned.command),learned.command,true)\nreturn\nend\nlocal listPage=text:match(\"^danh sach chuc nang ?(%d*)$\")or text:match(\"^liet ke chuc nang ?(%d*)$\")\nor text:match(\"^list controls ?(%d*)$\")or text:match(\"^list features ?(%d*)$\")\nif text==\"cac chuc nang\"then listPage=\"\"end\nif listPage~=nil the","n\nCross.say(\"user\",prompt)\nif Cross.Perm and Cross.Perm.Ui==false then reply(\"Quyền điều khiển UI của Cross đang tắt.\");return end\nlocal entries,names=controls(),{}\nlocal pages=math.max(1,math.ceil(#entries/15))\nlocal page=math.clamp(tonumber(listPage)or 1,1,pages)\nfor i=(page-1)*15+1,math.min(#entries,page*15)do\nlocal e=entries[i];table.insert(names,e.Tab..\": \"..e.Title..\" [\"..e.Kind..\"]\")\nend\nreply(#entries==0 and\"Chưa tìm thấy control nào trong cửa sổ xNgot.\"or(\"Control \"..page..\"/\"..pages..\": \"..table.concat(names,\"; \")..(pages>1 and\". Dùng 'danh sách chức năng \"..math.min(page+1,pages)..\"' để xem tiếp.\"or\"\")))\nreturn\nend\nlocal matches=choose(text)\nif#matches==0 then\nif Cross.Clarify then\nCross.say(\"user\",prompt)\nreply(\"Mình vẫn chưa tìm thấy control. Hãy ghi tên tab, tên chức năng và bật/tắt, hoặc trả lời Không để hủy.\")\nreturn\nend\nlocal intent=direction(text)\nlocal knownMusic=hasWord(text,\"nhac\")or hasWord(text,\"music\")or hasWord(text,\"song\")or hasWord(text,\"bai\")or hasWord(text,\"timer\")or hasWord(text,\"hen gio\")\nif intent and not knownMusic and#controls()>0 and not(Cross.Perm and Cross.Perm.Ui==false)then\nCross.say(\"user\",prompt)\nif not Cross.Enabled then Cross.setEnabled(true)end\nCross.Clarify={Phrase=safePhrase(prompt),Direction=intent,Expires=os.clock()+60}\nreply(\"Mình chưa rõ chức năng đó. Hãy nói rõ tên tab, tên chức năng và hành động; trả lời Không để hủy.\")\nreturn\nend\nreturn __crossAskBase(prompt)\nend\nif not Cross.Clarify and#matches==1 and matches[1].Kind==\"Section\"and normalize(matches[1].Title)==\"music\"\nand not hasWord(text,\"section\")and not hasWord(text,\"muc\")\nand(hasWord(text,\"nhac\")or hasWord(text,\"music\"))\nand(hasWord(text,\"play\")or hasWord(text,\"phat\")or hasWord(text,\"nghe\")or hasWord(text,\"mo\")or hasWord(text,\"bat\"))then\nreturn __crossAskBase(prompt)\nend\nCross.say(\"user\",prompt)\nif not Cross.Enabled then Cross.setEnabled(true)end\nif#matches>1 then\nlocal names={};for _,e in ipairs(matches)do table.insert(names,e.Tab..\": \"..e.Title)end\nreply(\"Có nhiều control trùng tên: \"..table.concat(names,","\"; \")..\". Hãy ghi thêm tên tab.\");return\nend\nlocal clarification=Cross.Clarify\nCross.Clarify=nil\noffer(matches[1],text,prompt,false,clarification)\nend\nend\ndo\nlocal previousExpand=Isl.expand\nIsl.expand=function(page)\nif page==\"Cross\"then\nlocal ok=pcall(previousExpand,\"Cross\")\npcall(function()Fwd.crossOpen(\"chat\")end)\nreturn ok\nend\nreturn previousExpand(page)\nend\nFwd.islandExpand=Isl.expand\nend\nfunction Cross.clearChat()\nCross.Pending=nil\nCross.Clarify=nil\ntable.clear(Cross.Chat)\nCross.ChatVersion+=1\nCross.Bubble.Full=\"\"\nCross.Bubble.Shown=\"\"\nCross.Bubble.Entry=nil\nCross.Echo=\"\"\nend\nfunction Cross.shutdown()\nCross.setEnabled(false)\nCross.clearChat()\nend\ntask.spawn(function()\nif Music.Remote and type(Music.Remote.LoadDownloaded)==\"function\"then\nlocal ok,err=pcall(Music.Remote.LoadDownloaded)\nif not ok then warn(\"[xNgotStudio] Music downloaded: \"..tostring(err))end\nelseif Music.Remote and type(Music.Remote.Load)==\"function\"then\nlocal ok,err=pcall(Music.Remote.Load)\nif not ok then warn(\"[xNgotStudio] Music AI: \"..tostring(err))end\nend\nend)\nlocal env=type(getgenv)==\"function\"and getgenv()or _G\nlocal previous=env.__xNgotStudioFullDynamic\nif previous and type(previous.Destroy)==\"function\"then pcall(previous.Destroy,previous)end\nState.Ready=true\nblur.Size=0\nSpr.springIslandY:Set(ISLAND.Top)\nIsl.settleIsland()\nCross.Lang=Settings.Language\nlocal API={Version=\"3.0.0\",Enabled=true,Settings=Settings,OriginalUI=true,Root=gui}\nfunction API:Notify(title,message,kind,duration)\nif not self.Enabled then return false end\nnotify(tostring(title or\"xNgotStudio\"),tostring(message or\"\"),kind or\"info\",duration or Settings.Duration,true)\nreturn true\nend\nlocal gameplayActivityGeneration=0\nfunction API:GameplayActivity(title,message,duration,kind)\nif not self.Enabled then return false end\ngameplayActivityGeneration+=1\nlocal generation=gameplayActivityGeneration\nlocal text=tostring(message or\"\")\nlocal shade=kind==\"success\"and Static.Green or Static.Blue\nActivities.Gameplay={\nTitle=tostring(title or\"Auto Farm\"),\nColor=shade,\nValue=function()ret","urn text end,\nShort=function()return text end,\n}\nrefreshActivity()\ntask.delay(math.clamp(tonumber(duration)or 11,3,30),function()\nif gameplayActivityGeneration~=generation then return end\nActivities.Gameplay=nil\nif gui.Parent then refreshActivity()end\nend)\nreturn true\nend\nfunction API:Enable(on)\nself.Enabled=on and true or false\ngui.Visible=self.Enabled and(not __hostWindow or __hostWindow.__IslandReady==true)\nRing.Holder.Visible=self.Enabled\nif not self.Enabled then\nif Isl.collapse then Isl.collapse(true,true)end\nelse\nIsl.settleIsland()\nend\nend\nfunction API:Set(name,value)\nif name==\"Fps\"then setFpsActivity(value and true or false)\nelseif name==\"Ping\"then setPingActivity(value and true or false)\nelseif name==\"Clock\"then setClockActivity(value and true or false)\nelseif name==\"Language\"then\nSettings.Language=\"en\"\nCross.Lang=\"en\"\nFwd.applyLanguage()\nFwd.applyLanguage()\nelseif Settings[name]~=nil then\nSettings[name]=value\nif name==\"Ring\"then\nif not value then Ring.ringHide()else Isl.settleIsland()end\nelseif name==\"Split\"then\nif Fwd.islandSync then Fwd.islandSync()end\nelseif name==\"Expand\"and not value then\nif Isl.collapse then Isl.collapse(true,true)end\nelseif name==\"Reverb\"and sfxReverb then sfxReverb.Enabled=value end\nend\nend\nfunction API:Theme(n)applyTheme(math.clamp(math.floor(tonumber(n)or 1),1,#Palettes))end\nfunction API:Accent(n)applyAccent(math.clamp(math.floor(tonumber(n)or 1),1,#Accents))end\nfunction API:MusicSelect(n,play)\nMusic.Select(math.clamp(math.floor(tonumber(n)or 1),1,#Music.Tracks),play~=false)\nend\nfunction API:MusicCatalog()\nlocal catalog={}\nfor index,track in ipairs(Music.Tracks)do\nif track.Remote then\ncatalog[#catalog+1]={\nIndex=index,\nName=track.Name,\nArtist=track.Artist or\"\",\nGenre=track.Mood or\"\",\nDesc=track.Desc or track.Mood or\"\",\nDuration=track.Duration or\"\",\nThumbnail=track.Thumbnail or\"\",\nValue=track.Value or\"\",\nCoverAsset=track.CoverAsset or\"\",\nRow=track.Row,\n}\nend\nend\nreturn catalog,Music.Remote.State,Music.Remote.Supported()\nend\nfunction API:OnMusicCatalogChanged(callback)\nif type(ca","llback)~=\"function\"then return function()end end\ntable.insert(Music.Remote.Listeners,callback)\nreturn function()\nlocal index=table.find(Music.Remote.Listeners,callback)\nif index then table.remove(Music.Remote.Listeners,index)end\nend\nend\nfunction API:OnMusicChanged(callback)\nif type(callback)~=\"function\"then return function()end end\ntable.insert(Music.Listeners,callback)\nreturn function()\nlocal index=table.find(Music.Listeners,callback)\nif index then table.remove(Music.Listeners,index)end\nend\nend\nfunction API:DemoDownload()\nif Activities.Download then return end\ndownloadValue=0\nActivities.Download={Title=\"Download\",Label=\"Demo · xngot_pack.zip\",FileName=\"xngot_pack.zip\",Color=Static.Blue,\nValue=function()return string.format(\"%d%%\",math.floor(downloadValue*100+0.5))end,\nShort=function()return string.format(\"%d%%\",math.floor(downloadValue*100+0.5))end,\nRing=function()return downloadValue end,RingMode=\"fill\"}\nrefreshActivity()\ntask.spawn(function()\nlocal started=os.clock()\nwhile gui.Parent and os.clock()-started<4.5 do\nlocal alpha=math.clamp((os.clock()-started)/4.5,0,1)\ndownloadValue=alpha*alpha*(3-2*alpha)\ntask.wait(0.05)\nend\ndownloadValue=1\nActivities.Download=nil\nrefreshActivity()\nnotify(\"Download complete\",\"Demo progress finished\",\"success\",2.8,true)\nend)\nend\nfunction API:Expand(page)if not self.Enabled then return end Isl.expand(page or\"Home\")end\nfunction API:Collapse()Isl.collapse(false,false)end\nfunction API:Timer(seconds)startTimer(math.clamp(tonumber(seconds)or 60,1,86400))end\nfunction API:StopTimer()stopTimer()end\nfunction API:ExtendTimer(seconds)extendTimer(tonumber(seconds)or 30)end\nfunction API:WatchToggle()stopwatchToggle()end\nfunction API:WatchLap()stopwatchLap()end\nfunction API:WatchReset()stopwatchReset()end\nfunction API:PlayMusic()Music.Toggle()end\nfunction API:NextMusic(n)Music.Next(tonumber(n)or 1)end\nfunction API:MusicVolume(n)Music.SetVolume(math.clamp(tonumber(n)or 40,0,100))end\nfunction API:MusicSpeed(n)Music.SetTempo(math.clamp(tonumber(n)or 1,0.5,2))end\nfunction API:MusicMode(name,value)\ni","f name==\"Auto\"or name==\"Shuffle\"or name==\"RepeatOne\"or name==\"ShowIsland\"then Music[name]=value and true or fal